from datetime import datetime, timezone


def main():
    with open(sys.argv[1], "r", encoding="utf-8") as f:
        data = json.load(f)

    as_of = datetime.fromisoformat(data["as_of"])

    results = []
    for r in data.get("reminders", []):
        if r.get("completed"):
            continue
        due_val = r.get("due")
        if due_val is None or not isinstance(due_val, str):
            continue
        try:
            due_dt = datetime.fromisoformat(due_val)
        except ValueError:
            continue
        # skip naive datetime (no timezone offset)
        if due_dt.tzinfo is None:
            continue

        # compare actual instants; include due AT OR BEFORE as_of
        if due_dt <= as_of:
            due_utc = due_dt.astimezone(timezone.utc)
            results.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": due_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "_due": due_dt,
            })

    results.sort(key=lambda x: (x["_due"], x["id"]))
    out = [{"id": x["id"], "title": x["title"], "due_utc": x["due_utc"]} for x in results]
    print(json.dumps(out))


main()"}

